local gear={}
for i=0,31 do
 local function point(j) local r=(j%4==1 or j%4==2) and 9 or 7;local t=j*math.pi/16;return 10+math.cos(t)*r,10+math.sin(t)*r end
 local x1,y1=point(i);local x2,y2=point((i+1)%32);gear[#gear+1]={x1,y1,x2,y2}
end
for i=0,15 do local t=i*math.pi/8;local u=(i+1)*math.pi/8;gear[#gear+1]={10+math.cos(t)*3,10+math.sin(t)*3,10+math.cos(u)*3,10+math.sin(u)*3} end
